package com.bookflow.services.application;
import com.bookflow.businesses.authorization.*; import com.bookflow.services.api.*; import com.bookflow.shared.error.*; import org.springframework.context.annotation.Profile; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Service @Profile("!test") public class ServiceCatalogService {private final TenantAuthorizationService auth;private final JdbcTemplate j;public ServiceCatalogService(TenantAuthorizationService a,JdbcTemplate j){auth=a;this.j=j;} private void valid(ServiceRequest r,boolean create){if(r==null||(create&&(r.name()==null||r.price()==null||r.currency()==null||r.durationMinutes()==null))||(!create&&r.name()==null&&r.description()==null&&r.price()==null&&r.currency()==null&&r.durationMinutes()==null&&r.bufferBeforeMinutes()==null&&r.bufferAfterMinutes()==null)||(r.price()!=null&&r.price().compareTo(BigDecimal.ZERO)<=0)||(r.currency()!=null&&!r.currency().matches("[A-Za-z]{3}"))||(r.durationMinutes()!=null&&r.durationMinutes()<=0)||(r.bufferBeforeMinutes()!=null&&r.bufferBeforeMinutes()<0)||(r.bufferAfterMinutes()!=null&&r.bufferAfterMinutes()<0))throw new RequestValidationException(List.of(new ApiFieldViolation("$","Invalid","Service request is invalid.")));}
 @Transactional public ServiceResponse create(UUID u,UUID t,ServiceRequest r){auth.requirePermission(u,t,TenantPermission.SERVICE_MANAGE);valid(r,true);UUID id=UUID.randomUUID();j.update("INSERT INTO services(id,tenant_id,name,description,price,currency,duration_minutes,buffer_before_minutes,buffer_after_minutes) VALUES(?,?,?,?,?,?,?,?,?)",id,t,r.name().strip(),r.description(),r.price(),r.currency().toUpperCase(Locale.ROOT),r.durationMinutes(),Optional.ofNullable(r.bufferBeforeMinutes()).orElse(0),Optional.ofNullable(r.bufferAfterMinutes()).orElse(0));return get0(t,id);}
 public List<ServiceResponse> list(UUID u,UUID t){auth.requirePermission(u,t,TenantPermission.SERVICE_VIEW);return j.query("SELECT id FROM services WHERE tenant_id=? AND status='ACTIVE' ORDER BY created_at,id",(rs,n)->get0(t,rs.getObject(1,UUID.class)),t);}
 public ServiceResponse get(UUID u,UUID t,UUID id){auth.requirePermission(u,t,TenantPermission.SERVICE_VIEW);return get0(t,id);}
 @Transactional public ServiceResponse update(UUID u,UUID t,UUID id,ServiceRequest r){auth.requirePermission(u,t,TenantPermission.SERVICE_MANAGE);valid(r,false);int n=j.update("UPDATE services SET name=COALESCE(?,name),description=COALESCE(?,description),price=COALESCE(?,price),currency=COALESCE(?,currency),duration_minutes=COALESCE(?,duration_minutes),buffer_before_minutes=COALESCE(?,buffer_before_minutes),buffer_after_minutes=COALESCE(?,buffer_after_minutes),updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND id=? AND status='ACTIVE'",r.name()==null?null:r.name().strip(),r.description(),r.price(),r.currency()==null?null:r.currency().toUpperCase(Locale.ROOT),r.durationMinutes(),r.bufferBeforeMinutes(),r.bufferAfterMinutes(),t,id);if(n==0)throw new ResourceNotFoundException();return get0(t,id);}
 @Transactional public void archive(UUID u,UUID t,UUID id){auth.requirePermission(u,t,TenantPermission.SERVICE_MANAGE);if(j.update("UPDATE services SET status='ARCHIVED',updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND id=? AND status='ACTIVE'",t,id)==0&&!exists(t,id))throw new ResourceNotFoundException();}
 @Transactional public void branch(UUID u,UUID t,UUID s,UUID b,boolean add){auth.requirePermission(u,t,TenantPermission.SERVICE_MANAGE);if(!active(t,s,"services")||!active(t,b,"branches"))throw new ResourceNotFoundException();if(add)j.update("INSERT INTO branch_services(tenant_id,branch_id,service_id) VALUES(?,?,?) ON CONFLICT DO NOTHING",t,b,s);else j.update("DELETE FROM branch_services WHERE tenant_id=? AND branch_id=? AND service_id=?",t,b,s);}
 @Transactional public void employee(UUID u,UUID t,UUID s,UUID e,boolean add){auth.requirePermission(u,t,TenantPermission.SERVICE_MANAGE);if(!active(t,s,"services")||!active(t,e,"employees"))throw new ResourceNotFoundException();if(add&&!Boolean.TRUE.equals(j.queryForObject("SELECT EXISTS(SELECT 1 FROM branch_services bs JOIN employee_branch_assignments ea ON ea.tenant_id=bs.tenant_id AND ea.branch_id=bs.branch_id JOIN branches b ON b.tenant_id=bs.tenant_id AND b.id=bs.branch_id AND b.status='ACTIVE' WHERE bs.tenant_id=? AND bs.service_id=? AND ea.employee_id=?)",Boolean.class,t,s,e)))throw new RequestValidationException(List.of(new ApiFieldViolation("employeeId","BranchOverlap","Employee and service need an active branch in common.")));if(add)j.update("INSERT INTO employee_services(tenant_id,employee_id,service_id) VALUES(?,?,?) ON CONFLICT DO NOTHING",t,e,s);else j.update("DELETE FROM employee_services WHERE tenant_id=? AND employee_id=? AND service_id=?",t,e,s);}
 public List<UUID> branches(UUID u,UUID t,UUID s){auth.requirePermission(u,t,TenantPermission.SERVICE_VIEW);get0(t,s);return j.queryForList("SELECT branch_id FROM branch_services WHERE tenant_id=? AND service_id=? ORDER BY branch_id",UUID.class,t,s);} public List<UUID> employees(UUID u,UUID t,UUID s){auth.requirePermission(u,t,TenantPermission.SERVICE_VIEW);get0(t,s);return j.queryForList("SELECT employee_id FROM employee_services WHERE tenant_id=? AND service_id=? ORDER BY employee_id",UUID.class,t,s);}private boolean active(UUID t,UUID id,String table){return Boolean.TRUE.equals(j.queryForObject("SELECT EXISTS(SELECT 1 FROM "+table+" WHERE tenant_id=? AND id=? AND status='ACTIVE')",Boolean.class,t,id));}private boolean exists(UUID t,UUID id){return Boolean.TRUE.equals(j.queryForObject("SELECT EXISTS(SELECT 1 FROM services WHERE tenant_id=? AND id=?)",Boolean.class,t,id));}private ServiceResponse get0(UUID t,UUID id){return j.query("SELECT id,tenant_id,name,description,price,currency,duration_minutes,buffer_before_minutes,buffer_after_minutes,status,created_at,updated_at FROM services WHERE tenant_id=? AND id=? AND status='ACTIVE'",rs->{if(!rs.next())throw new ResourceNotFoundException();return new ServiceResponse(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getString(3),rs.getString(4),rs.getBigDecimal(5),rs.getString(6),rs.getInt(7),rs.getInt(8),rs.getInt(9),rs.getString(10),j.queryForList("SELECT branch_id FROM branch_services WHERE tenant_id=? AND service_id=?",UUID.class,t,id),j.queryForList("SELECT employee_id FROM employee_services WHERE tenant_id=? AND service_id=?",UUID.class,t,id),rs.getTimestamp(11).toInstant(),rs.getTimestamp(12).toInstant());},t,id);}}
